import { readFileSync, writeFileSync } from 'node:fs'

const FILE = new URL('../prices.json', import.meta.url)
const LB_PER_TON = 2204.62

const prev = (() => {
  try { return JSON.parse(readFileSync(FILE, 'utf8')) } catch { return { metals: {}, wages: {} } }
